def sh(s,a,b,size,subject,camera,action,actions=None,visible=None,touch="none",touch_who=None,revealing=False):
    if visible==[]: subject=None
    d={"s":s,"from":a,"to":b,"size":size,"subject":subject,"camera":camera,"action":action,"actions":actions or [action],"touch":touch,"revealing":revealing}
    if visible is not None: d["visible"]=visible
    if touch_who: d["touch_who"]=touch_who
    return d

def prompt(sound,style,refs,cast,opening,budgets,intent,pace,shots,audio,noline,bg=False):
    L=[sound,style,LOOK]+refs+[cast,opening]+budgets+intent+[pace]
    for s in shots: L.append("S%d %.1f-%.1fs · %s"%(s["s"],s["a"],s["b"],s["line"]))
    L.append(LANG)
    L+=audio
    L.append(noline)
    L+=RESTR
    if bg: L.append(BG)
    L.append(LAST)
    return "\n".join(L)

